  if NEW.data_scope NOT IN ('live','qa-bots-v1') OR NEW.data_scope<>OLD.data_scope OR (NEW.employee_id IS NOT NULL AND ((NEW.data_scope='qa-bots-v1' AND NOT EXISTS (SELECT 1 FROM employees r WHERE r.id=NEW.employee_id AND r.data_scope=NEW.data_scope)) OR EXISTS (SELECT 1 FROM employees r WHERE r.id=NEW.employee_id AND r.data_scope<>NEW.data_scope))) OR (NEW.required_manager_id IS NOT NULL AND ((NEW.data_scope='qa-bots-v1' AND NOT EXISTS (SELECT 1 FROM employees r WHERE r.id=NEW.required_manager_id AND r.data_scope=NEW.data_scope)) OR EXISTS (SELECT 1 FROM employees r WHERE r.id=NEW.required_manager_id AND r.data_scope<>NEW.data_scope))) OR (NEW.reviewer_id IS NOT NULL AND ((NEW.data_scope='qa-bots-v1' AND NOT EXISTS (SELECT 1 FROM employees r WHERE r.id=NEW.reviewer_id AND r.data_scope=NEW.data_scope)) OR EXISTS (SELECT 1 FROM employees r WHERE r.id=NEW.reviewer_id AND r.data_scope<>NEW.data_scope))) OR (NEW.attachment_id IS NOT NULL AND ((NEW.data_scope='qa-bots-v1' AND NOT EXISTS (SELECT 1 FROM documents r WHERE r.id=NEW.attachment_id AND r.data_scope=NEW.data_scope)) OR EXISTS (SELECT 1 FROM documents r WHERE r.id=NEW.attachment_id AND r.data_scope<>NEW.data_scope))) then raise exception 'Data scope boundary rejected this operation'; end if;
